    return glm::vec3(0.0f);
}
glm::vec3 grad = spikyGrad * std::pow(h - rlen, 2) * (r / rlen);
float coeff = -mass * (pi->pressure / (pi->density * pi->density) + pj->pressure / (pj->density * pj->density));
return coeff * grad;

